package authoring

// PromptContract is the model-facing planning contract. Snapshot handles and
// permissions are added by the caller after this stable prefix.
const PromptContract = `Return exactly one JSON object, an IntentSpec with schema_version=1. Do not emit ProgramIR, VM IDs, mutation, hashes, layout of scripts, or action trees.
Fields: ready (boolean), title (1..120 characters), goal (1..2000), targets, states, assets, script_slots, required_extensions, assumptions, success_criteria, missing_questions. Use arrays even when empty. If essential decisions are missing, set ready=false and put focused questions in missing_questions; no script generation may follow.
Every local key is 1..80 ASCII letters/digits/underscore/hyphen, starting with a letter. Reuse exactly the supplied handles for existing objects. Display names are separate from keys.
targets: {key,name,kind:"sprite"|"stage",disposition:"current"|"existing"|"new",target_ref?:{kind:"current_target"|"stage"|"existing_sprite",name?:string}}. single_sprite allows only one current target. New targets require project scope and kind=sprite; their names must not already exist.
states: {key,name,kind:"variable"|"list"|"broadcast",scope:"global"|"local",owner?:target_key,disposition:"new"|"reuse",initial?:scalar|scalar[]}. Local states require an explicit sprite owner; global states have no owner. Broadcasts are global without initial. Reuse preserves the snapshot value: omit initial. Do not redeclare an existing state as new. Exact trustedSnapshot state handles may be referenced directly by a slot without repeating a states declaration; the service freezes them as reuse with their trusted scope/owner and preserved value. Display names and unknown handles never receive this treatment.
assets: {key,owner:target_key,kind:"sprite"|"costume"|"backdrop"|"sound",name,purpose,disposition:"new"|"reuse",search_terms:string[],source?:object,x?:integer,y?:integer,size?:integer}. New assets are project-only. Every new sprite target needs exactly one new sprite asset with the same owner/name. Default source is scratch_library using search_terms; optional fully specified sources must obey the supplied resource contract. Reuse only assets listed in the trusted snapshot. Backdrops belong to a stage. Resource matching and any paid generation remain separate from planning.
script_slots: {key,owner:target_key,trigger,purpose,reads:string[],writes:string[],emits:string[],receives:string[],assets:string[],edit_ref?:trusted_edit_ref}. One slot is one event script. Declare data reads/writes separately from broadcast emits/receives. assets lists permitted asset or target keys. Triggers: {kind:"green_flag"|"sprite_clicked"|"clone_started"}; {kind:"key_pressed",key:"left arrow" etc}; {kind:"broadcast_received",state:broadcast_key}; {kind:"backdrop_switched",asset:backdrop_key}; {kind:"timer_reached",seconds:number}. A broadcast trigger must also appear in receives. Do not infer generation dependency cycles from runtime broadcasts. External existing producer/consumer endpoints are allowed.
For modify, select only authorized snapshot edit_ref values; append/rewrite must omit edit_ref. Do not invent script IDs. Procedures/custom blocks require the legacy path and must be reported unsupported rather than silently dropped.
Only explicitly permitted extensions may be required. Short purpose text replaces an action tree; keep all cross-script state/broadcast/resource interfaces explicit.`

const CompactPromptContract = `Return exactly one slot response object: {"slot_id":"the supplied slot key","status":"ready","body":[...],"revision":null}. Put only this frozen slot's commands in body; still return the complete four-field response object. Do not add hats, IDs, metadata, declarations, procedures, layout, removal lists, or change target/edit permissions.
Each block uses {"opcode":"full native opcode","fields":{},"inputs":{},"substacks":{}}; unused containers may be omitted. Preserve exact named ports. One command per array entry. C blocks use named SUBSTACK/SUBSTACK2 arrays. Hats are inserted by the service. Reporters are nested opcode objects directly in an input.
Number/angle ports require JSON numbers; text/color ports require strings. Never silently cast a numeric literal to text or text to number. Boolean inputs require explicit boolean reporter blocks; true/false/null are not boolean reporter shorthand.
A resolved field uses {"state":"a permitted state handle"}. An ordinary input may use {"state":"variable-or-list-handle"}, which becomes a reporter. Broadcast send inputs use {"state":"broadcast-handle"}. Resource menus use {"asset":"asset-handle"}, {"target":"sprite-handle"}, or an explicitly allowed {"builtin":"mouse"|"edge"|"random"|"myself"}; never raw display names. Only handles and accesses listed for this slot are permitted.
If the frozen interface/profile lacks a needed capability, emit {"slot_id":"same slot","status":"needs_revision","body":null,"revision":{"reason":"missing_capability"|"missing_interface"|"unsupported","requested_opcodes":[],"explanation":"short explanation"}}. This requests a separately authorized revision; it does not grant permission to add a state, script, extension, or arbitrary opcode.`

// The lightweight wire schemas are for request validation and non-strict JSON
// transports. Opcode-specific strict schemas must be compiled from a frozen
// profile by the provider layer; these schemas must not be silently advertised
// as that stronger guarantee.
func IntentJSONSchema() map[string]any {
	str := func() map[string]any { return map[string]any{"type": "string", "maxLength": 120} }
	array := func(item any, max int) map[string]any {
		return map[string]any{"type": "array", "items": item, "maxItems": max}
	}
	object := func(properties map[string]any, required ...string) map[string]any {
		return map[string]any{"type": "object", "properties": properties, "required": required, "additionalProperties": false}
	}
	scalar := map[string]any{"type": []string{"string", "number", "boolean"}}
	target := object(map[string]any{"key": str(), "name": str(), "kind": map[string]any{"enum": []string{"sprite", "stage"}}, "disposition": map[string]any{"enum": []string{"current", "existing", "new"}}, "target_ref": map[string]any{"type": "object"}}, "key", "name", "kind", "disposition")
	state := object(map[string]any{"key": str(), "name": str(), "kind": map[string]any{"enum": []string{"variable", "list", "broadcast"}}, "scope": map[string]any{"enum": []string{"global", "local"}}, "owner": str(), "disposition": map[string]any{"enum": []string{"new", "reuse"}}, "initial": map[string]any{"anyOf": []any{scalar, array(scalar, 500)}}}, "key", "name", "kind", "scope", "disposition")
	asset := object(map[string]any{"key": str(), "owner": str(), "kind": map[string]any{"enum": []string{"sprite", "costume", "backdrop", "sound"}}, "name": str(), "purpose": str(), "disposition": map[string]any{"enum": []string{"new", "reuse"}}, "search_terms": array(str(), 12), "source": map[string]any{"type": "object"}, "x": map[string]any{"type": "integer"}, "y": map[string]any{"type": "integer"}, "size": map[string]any{"type": "integer"}}, "key", "owner", "kind", "name", "purpose", "disposition", "search_terms")
	trigger := object(map[string]any{"kind": map[string]any{"enum": []string{"green_flag", "key_pressed", "sprite_clicked", "broadcast_received", "backdrop_switched", "clone_started", "timer_reached"}}, "key": str(), "state": str(), "asset": str(), "seconds": map[string]any{"type": "number", "minimum": 0}}, "kind")
	slot := object(map[string]any{"key": str(), "owner": str(), "trigger": trigger, "purpose": str(), "reads": array(str(), 150), "writes": array(str(), 150), "emits": array(str(), 150), "receives": array(str(), 150), "assets": array(str(), 36), "edit_ref": str()}, "key", "owner", "trigger", "purpose", "reads", "writes", "emits", "receives", "assets")
	return object(map[string]any{"schema_version": map[string]any{"const": 1}, "ready": map[string]any{"type": "boolean"}, "title": str(), "goal": map[string]any{"type": "string", "maxLength": 2000}, "targets": array(target, 12), "states": array(state, 150), "assets": array(asset, 24), "script_slots": array(slot, 80), "required_extensions": array(map[string]any{"enum": []string{"pen", "music", "text2speech"}}, 3), "assumptions": array(str(), 10), "success_criteria": array(str(), 40), "missing_questions": array(str(), 20)}, "schema_version", "ready", "title", "goal", "targets", "states", "assets", "script_slots", "required_extensions", "assumptions", "success_criteria", "missing_questions")
}
func CompactJSONSchema() map[string]any {
	return map[string]any{"type": "object", "additionalProperties": false, "required": []string{"slot_id", "status", "body", "revision"}, "properties": map[string]any{"slot_id": map[string]any{"type": "string", "maxLength": 80}, "status": map[string]any{"enum": []string{"ready", "needs_revision"}}, "body": map[string]any{"type": []string{"array", "null"}, "maxItems": 120, "items": map[string]any{"type": "object"}}, "revision": map[string]any{"type": []string{"object", "null"}}}}
}
